mapper.select:
SELECT B.id AS sdk_group_percentage_id, B.tag AS group_tag, B.exp_id AS percentage_exp_id, B.exp_name AS percentage_exp_name, B.percentage AS group_percentage, B.status AS group_percentage_status, C.id AS sdk_group_targeting_id, C.name, C.priority, C.app_version, C.sdk_version, C.location_list, C.make_list, C.osv_list, A.id AS sdk_traffic_id, D.exp_id AS target_percentage_exp_id, D.exp_name AS target_percentage_exp_name, D.id AS sdk_targeting_percentage_id, D.tag AS target_group_tag, D.percentage AS target_group_percentage, D.status AS target_group_percentage_status, A.supplier_ids FROM sdk_group A JOIN ( SELECT X.*, Y.exp_name FROM sdk_group_percentage X LEFT OUTER JOIN ( SELECT id, experiment_name AS exp_name FROM sdk_experiment WHERE experiment_type = 1 AND status = 1 ) Y ON X.exp_id = Y.id ) B ON A.sdk_group_percentage_id = B.id JOIN sdk_group_targeting C ON A.sdk_group_targeting_id = C.id JOIN ( SELECT X.*, Y.exp_name FROM sdk_targeting_percentage X LEFT OUTER JOIN ( SELECT id, experiment_name AS exp_name FROM sdk_experiment WHERE experiment_type = 2 AND status = 1 ) Y ON X.exp_id = Y.id ) D ON A.sdk_group_targeting_percentage_id = D.id WHERE A.adspot_id = #{adspotId}
AND A.sdk_group_percentage_id = #{percentageId}
ORDER BY B.id, C.priority ASC

SELECT id, supplier_ids
FROM sdk_group
WHERE adspot_id = #{adspotId} AND id = #{sdkTrafficId}

mapper.update:
UPDATE sdk_group
SET supplier_ids = #{supplierIds}
WHERE id = #{sdkTrafficId}

mapper.select:
SELECT id, supplier_ids
FROM sdk_group
WHERE adspot_id = #{adspotId} AND supplier_ids rlike #{sdkChannelId}

SELECT A.id, D.platform_type, D.id AS media_id, D.media_name AS media_name, C.id AS adspot_id, C.adspot_name, C.adspot_type, A.group_tag, A.sdk_group_id, A.sdk_group_percentage_id, A.sdk_group_targeting_id, A.sdk_group_targeting_percentage_id, B.id AS supplier_id, IF(COALESCE(A.name, "") = "", B.adn_name, A.name) AS sdk_channel_name, A.name AS sdk_channel_alias, A.executeStatus AS status, A.is_auto_create, A.supplier_params, A.is_head_bidding, A.bid_ratio, A.location_list, A.make_list, A.osv_list, A.app_versions, A.daily_req_limit, A.daily_imp_limit, A.device_daily_req_limit, A.device_daily_imp_limit, A.device_request_interval FROM ( SELECT M.*, N.id AS sdk_group_id, N.sdk_group_percentage_id, N.sdk_group_targeting_id, N.sdk_group_targeting_percentage_id, CONCAT( IF(P.percentage != 100, CONCAT(P.tag, '-'), ''), Q.name, IF(R.percentage != 100, CONCAT('-', R.tag), '') ) AS group_tag, IF(M.status = 0, 0, IF(INSTR(N.supplier_ids, M.id) > 0, 1, 0)) AS executeStatus FROM ( SELECT * FROM adspot_sdk_channel WHERE adn_id = #{channelId} AND mark_delete = 0 ) M JOIN sdk_group N ON M.adspot_id = N.adspot_id JOIN sdk_group_percentage P ON N.sdk_group_percentage_id = P.id JOIN sdk_group_targeting Q ON N.sdk_group_targeting_id = Q.id JOIN sdk_targeting_percentage R ON N.sdk_group_targeting_percentage_id = R.id ) A INNER JOIN ( SELECT * FROM sdk_adn ) B ON A.adn_id = B.id JOIN adspot C ON A.adspot_id = C.id JOIN media D ON C.media_id = D.id WHERE C.status = 1 AND C.mark_delete = 0
AND A.executeStatus = #{status}
AND D.id in
#{item}
AND (C.id = #{searchText} OR C.adspot_name rlike #{searchText} OR A.name rlike #{searchText} OR B.adn_name rlike #{searchText} OR A.supplier_params rlike #{searchText})
AND C.adspot_type in
#{item}

SELECT id AS sdk_group_id, supplier_ids
FROM sdk_group
WHERE id = #{sdkGroupId}
